// PhenoAge Calc — читает Results + Markers + Visits из книги phenoage.
// Формула: Levine et al. 2018 (Aging, Albany NY). CRP входит в мг/л (совпадает
// с ранее показанным значением; каноничная реализация берёт мг/дл — см. FORMULA_VERSION).
// Run Once for All Items.

const FORMULA_VERSION = 'Levine2018 / CRP=mg/L / 2026-09';

function safeAll(name) { try { return $(name).all().map(i => i.json); } catch (e) { return []; } }
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(String(v).replace(/\s/g, '').replace(',', '.'));
  return isNaN(n) ? null : n;
}
function d10(v) {
  let s = String(v == null ? '' : v).trim();
  let m = s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/);        // DD.MM.YYYY
  if (m) return m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  m = s.match(/^(\d{4})[.\/-](\d{1,2})[.\/-](\d{1,2})/);            // YYYY-MM-DD
  if (m) return m[1] + '-' + m[2].padStart(2, '0') + '-' + m[3].padStart(2, '0');
  return s.slice(0, 10);
}

const results = safeAll('Get Results');   // Visit_ID, Marker_ID, Value, Original_Unit, Lab_Min, Lab_Max
const markers = safeAll('Get Markers');   // Marker_ID, Name, Category, Standard_Unit, ...
const visits  = safeAll('Get Visits');    // Visit_ID, Date, Age_at_Visit, Lab_Name, Notes

// 9 маркеров PhenoAge -> ключ формулы. Сопоставляем по Marker_ID и по имени (на всякий).
const PHENO = {
  alb:   { ids: ['M008'], rx: /альбумин/i },
  creat: { ids: ['M004'], rx: /креатинин/i },
  gluc:  { ids: ['M003'], rx: /глюкоза/i },
  crp:   { ids: ['M024'], rx: /с-реактивн|срб|crp/i },
  lymph: { ids: ['M062'], rx: /лимфоциты\s*%/i },
  mcv:   { ids: ['M043'], rx: /mcv|средний объ[её]м эритроцит/i },
  rdw:   { ids: ['M049'], rx: /rdw|ширина распред.*эритроцит/i },
  alp:   { ids: ['M017'], rx: /щелочн(ая)? фосфатаз|alp|щф/i },
  wbc:   { ids: ['M039'], rx: /лейкоциты|wbc/i },
};
const idToName = {}; markers.forEach(m => { idToName[m.Marker_ID] = m.Name || ''; });
function keyForMarkerId(mid) {
  for (const [k, def] of Object.entries(PHENO)) {
    if (def.ids.includes(mid)) return k;
    if (def.rx.test(idToName[mid] || '')) return k;
  }
  return null;
}

// visit -> {date, age, values:{key:value}}
const visitMap = {};
visits.forEach(v => {
  visitMap[v.Visit_ID] = { visit_id: v.Visit_ID, date: d10(v.Date), age: num(v.Age_at_Visit), values: {} };
});
for (const r of results) {
  const vid = r.Visit_ID;
  const k = keyForMarkerId(r.Marker_ID);
  if (!k) continue;
  let val = num(r.Value);
  if (val == null) continue;
  // WBC иногда в тыс/мкл — численно то же, что 10^9/л. Ничего не конвертируем.
  if (!visitMap[vid]) visitMap[vid] = { visit_id: vid, date: d10(vid), age: null, values: {} };
  visitMap[vid].values[k] = val;
}

// Якорь возраста: самый свежий визит с Age_at_Visit -> линейно от него.
let ageAnchor = null;
Object.values(visitMap).filter(v => v.date && v.age != null)
  .sort((a, b) => a.date.localeCompare(b.date))
  .forEach(v => { ageAnchor = { date: v.date, age: v.age }; });
function ageAtDate(dateStr) {
  if (ageAnchor && dateStr) {
    const dd = (new Date(dateStr) - new Date(ageAnchor.date)) / (365.25 * 86400000);
    return Math.round((ageAnchor.age + dd) * 10) / 10;
  }
  const y = parseInt((dateStr || '').slice(0, 4), 10);
  return isNaN(y) ? null : (y - 1982);
}
function ageFor(v) { return v.age != null ? v.age : ageAtDate(v.date); }

function phenoAge(x) {
  const lnCRP = Math.log(Math.max(x.crp, 1e-4)); // CRP в мг/л
  const xb = -19.907
    - 0.0336 * x.alb + 0.0095 * x.creat + 0.1953 * x.gluc + 0.0954 * lnCRP
    - 0.0120 * x.lymph + 0.0268 * x.mcv + 0.3306 * x.rdw + 0.00188 * x.alp
    + 0.0554 * x.wbc + 0.0804 * x.age;
  const M = 1 - Math.exp(-1.51714 * Math.exp(xb) / 0.0076927);
  const pheno = 141.50 + Math.log(-0.00553 * Math.log(1 - M)) / 0.09165;
  return Math.round(pheno * 100) / 100;
}

const KEYS = Object.keys(PHENO);
const rows = [];
const series = [];

// (a) точки по каждому визиту с полным набором 9 + возраст
const sortedVisits = Object.values(visitMap).filter(v => v.date).sort((a, b) => a.date.localeCompare(b.date));
for (const v of sortedVisits) {
  const age = ageFor(v);
  const have = KEYS.filter(k => v.values[k] != null);
  const missing = KEYS.filter(k => v.values[k] == null);
  if (have.length === 9 && age != null) {
    const pa = phenoAge({ ...v.values, age });
    series.push({ date: v.date, chrono: age, pheno: pa, delta: Math.round((pa - age) * 100) / 100 });
  }
}

// (b) «текущая оценка»: последнее доступное значение каждого маркера + возраст на сегодня
const today = new Date(Date.now() + 10 * 3600 * 1000).toISOString().slice(0, 10);
const latestVal = {}; const latestDate = {};
for (const v of sortedVisits) {
  for (const k of KEYS) if (v.values[k] != null) { latestVal[k] = v.values[k]; latestDate[k] = v.date; }
}
const haveLatest = KEYS.filter(k => latestVal[k] != null);
const missingLatest = KEYS.filter(k => latestVal[k] == null);
const curAge = ageAtDate(today);
let current = null;
if (haveLatest.length === 9) {
  const pa = phenoAge({ ...latestVal, age: curAge });
  // вклад маркера: насколько сдвигается PhenoAge, если этот маркер заменить на «эталон здорового»
  const REF = { alb: 47, creat: 75, gluc: 4.6, crp: 0.5, lymph: 33, mcv: 88, rdw: 12.5, alp: 60, wbc: 5 };
  const contributions = {};
  for (const k of KEYS) {
    const swapped = { ...latestVal, age: curAge, [k]: REF[k] };
    contributions[k] = Math.round((pa - phenoAge(swapped)) * 100) / 100; // >0 = маркер старит
  }
  current = {
    date: today,
    chrono_age: Math.round(curAge * 10) / 10,
    phenoage: pa,
    delta: Math.round((pa - curAge) * 100) / 100,
    markers_used: haveLatest.map(k => k + ':' + latestVal[k] + '@' + latestDate[k]).join(', '),
    marker_contributions: contributions,
    marker_values: KEYS.reduce((o, k) => (o[k] = { value: latestVal[k], measured: latestDate[k] }, o), {}),
    oldest_marker_date: haveLatest.map(k => latestDate[k]).sort()[0],
    missing: '',
    formula_version: FORMULA_VERSION,
  };
  rows.push({
    date: today, chrono_age: current.chrono_age, phenoage: pa, delta: current.delta,
    markers_used: current.markers_used, missing: '', formula_version: FORMULA_VERSION,
  });
} else {
  current = { missing: missingLatest.join(', '), note: 'не хватает маркеров для расчёта' };
}

// (c) оценочная серия: для КАЖДОГО визита с полным CBC берём alb/crp по carry-forward
// (последнее известное на дату визита). Помечаем estimated=true.
const RARE = ['alb', 'crp'];
const series_estimated = [];
for (const v of sortedVisits) {
  const age = ageFor(v);
  if (age == null) continue;
  const vals = { ...v.values };
  let carried = [];
  for (const k of KEYS) {
    if (vals[k] != null) continue;
    if (!RARE.includes(k)) continue;
    // последнее известное значение k на дату <= v.date
    let best = null;
    for (const w of sortedVisits) {
      if (w.date <= v.date && w.values[k] != null) best = w.values[k];
    }
    if (best != null) { vals[k] = best; carried.push(k); }
  }
  const stillMissing = KEYS.filter(k => vals[k] == null);
  if (stillMissing.length === 0) {
    const pa = phenoAge({ ...vals, age });
    series_estimated.push({
      date: v.date, chrono: age, pheno: pa, delta: Math.round((pa - age) * 100) / 100,
      estimated: carried.length > 0, carried_forward: carried,
    });
  }
}

// строки истории (по визитам) для листа
for (const s of series) {
  rows.push({
    date: s.date, chrono_age: s.chrono, phenoage: s.pheno, delta: s.delta,
    markers_used: 'все 9 (визит)', missing: '', formula_version: FORMULA_VERSION,
  });
}

// строки листа для estimated-серии (только те, которых нет в точной series)
const exactDates = new Set(series.map(s => s.date));
for (const s of series_estimated) {
  if (exactDates.has(s.date)) continue;
  rows.push({
    date: s.date, chrono_age: s.chrono, phenoage: s.pheno, delta: s.delta,
    markers_used: 'оценка: ' + (s.carried_forward.length ? 'carry-forward ' + s.carried_forward.join('/') : 'все 9'),
    missing: '', formula_version: FORMULA_VERSION,
  });
}
return [{ json: { current, series, series_estimated, rows, missing_for_current: missingLatest } }];

// плоские строки для листа PhenoAge_Log
const rows = $input.first().json.rows || [];
return rows.map(r => ({ json: r }));

